"""Bounded negative experiments and hardware-counter attribution for tail attention."""
import csv,json
from .weights import ROOT

def main():
 root=ROOT/'artifacts/video_runtime_v1/tail_liveness_v1';variants={'late':'result.json','mean_detail_split':'split_result.json','query32':'query32_result.json','paired_conversion':'convert_result.json'}
 results={k:json.loads((root/v).read_text()) for k,v in variants.items()}
 lines=['# 补偿Attention：生命周期与布局瓶颈筛查','','## 本轮决定','','保留已验收补偿kernel，四个有明确假设的原型均未取得可推广收益，不接入默认配置，也不为失败原型跑完整视频。当前部署继续使用上一轮已验收的稳定softmax优化。没有改算法配置、权重、Full_Pset三档或精算预算。','', '## 输入与计时','','使用当前基础档city_walk_s701的clean历史，捕获chunk8、layer15、noisy step0的真实q/KV/summary/页面LUT。P432使用原始LUT；P216/288/360使用该历史前缀和固定10%候选LUT（超范围页取模，属于规约测试，不当作独立路由质量结果）。各版本同输入、CUDA Graph内执行，20轮交错顺序，每轮10次重放；表中为各轮均值的中位数。','', '| 原型 | P | 原版/ms | 候选/ms | 加速比 | mean/detail/LSE逐位一致 | 候选资源 |','|---|---:|---:|---:|---:|---|---|']
 for name,rows in results.items():
  for row in rows:
   med=row['median_ms'];resource=row['resources']['late'];lines.append(f"| {name} | {row['pages']} | {med['old']:.4f} | {med['late']:.4f} | {row['speedup']:.3f}× | {','.join(str(x['equal']) for x in row['contracts'])} | {resource} |")
 lines+=['', '各P的绝对时间跨编译、温度和时钟状态，不能用P216与P288时间倒推出复杂度；只有同一行交错配对用于判断收益。Nsight的replay/时钟设置也不与这些时间混算。','', '## 四项原型分别检验什么','','1. **late**：先消费完整均值，再逐项加载/消费三个detail，保持逐行算术结合顺序。P216/360略快，P288/432增加spill并回退，不能推广。','2. **mean_detail_split**：拆开均值和detail的累加器，让两个kernel各自处理。寄存器降至约231和128，但重复QK/softmax使P432约0.452→0.738ms，失败。均值/LSE有约1e-6的编译归约差，detail一致；没有降低精度，但也没有提速理由继续质量验收。','3. **query32**：依据占用率只试BQ64→32，页面块BR64和公式不变。共享内存56,832→39,936B，寄存器仍约250，CTA数量翻倍后P432约0.451→0.766ms，失败。没有继续扩成BQ/BR/warps/stages网格搜索。','4. **paired_conversion**：用inline PTX把BF16高低项在同一算子生成，保留原舍入点与两个乘积。四种P输出逐位一致，但P432约0.451→0.460ms，未改善layout转换成本，失败。','', '## 硬件profile改变了判断','','原P432 kernel：Nsight测得achieved occupancy12.26%，theoretical12.5%；255寄存器/thread、56,832B动态共享内存/CTA，均限制并发。DRAM吞吐3.76%，L2命中93.96%，L1/TEX吞吐79.41%，Tensor pipeline约30.9%，issue slot busy37.75%，62.22%调度周期无eligible warp。它不是HBM带宽饱和，也不是Tensor Core算满；此前PyTorch trace的occupancy=0是无效估计，已由硬件counter纠正。','', '进一步计数：shared-store bank conflict约9,545,193，shared-load约49,813。stall_wait24.92%、short_scoreboard12.45%、long_scoreboard11.63%、barrier9.31%、mio_throttle8.40%。这些指标口径不同，不能简单相加成时间归因。','', 'SASS与源行关联定位：BF16高低项转换行产生约5,971,968个excessive shared wavefront；softmax结果计算/reshape行约2,985,984；其余输出存储较少。源码行关联指向编译器在这些位置插入的布局转换，并不表示两条数值转换指令本身访问了shared memory。inline PTX试验没有消除它，下一步应直接看Triton布局和共享内存转置，不能再仅靠重排Python语句。','', '## 理论工作量与优化空间','','P432、H12、N4608、D128：QK为24.461GFLOPs；均值两项AV约12.231GFLOPs；三组detail两项AV按物理宽16计约4.586GFLOPs，主算术合计41.278GFLOPs。原约0.45ms对应约91.7TFLOP/s，低于大BF16 GEMM参考202.1TFLOP/s，但硬件counter说明差额涉及布局转换、同步与访存指令，不能把全部差额承诺为可回收收益。','', '拆分均值/detail重复一次QK，主算术升至约65.739GFLOPs（约+59.3%），还重复softmax/加载；其资源降低不足以抵消额外工作。BQ32算术量基本不变，但重复加载更多QK/页面数据且未降低到更高并发所需的寄存器水平。','', '目前没有新的部署加速比；本轮结果是排除这四条实现路线并锁定共享布局转换。保留原补偿作为后续对照。','', '## 实现和证据','','- [真实输入捕获](../../../local_experiments/video_runtime_v1/capture_tail.py)。','- [生命周期原型](../../../local_experiments/video_runtime_v1/tail_liveness.py)、[均值/detail拆分](../../../local_experiments/video_runtime_v1/tail_split.py)、[高低项成对转换](../../../local_experiments/video_runtime_v1/tail_convert.py)。','- [隔离检查与交错计时](../../../local_experiments/video_runtime_v1/check_tail_liveness.py)：默认late，`--split`、`--query32`、`--convert`分别复现。','- [Nsight入口](../../../local_experiments/video_runtime_v1/profile_tail_ncu.py)、[原硬件counter](ncu.csv)、[停顿counter](stalls.csv)、[SASS](source.csv)、[源行关联](source_correlated.csv)。','- [late结果](result.json)、[split结果](split_result.json)、[BQ32结果](query32_result.json)、[转换结果](convert_result.json)。','', '大型input.pt、source.ncu-rep及PTX保存在本机实验目录。未修改当前默认kernel，未运行15s/30s视频。']
 (root/'MODULE_DISTANCE.zh.md').write_text('\n'.join(lines)+'\n')
 (root/'summary.json').write_text(json.dumps(dict(deploy=False,reason='No broadly positive same-input tail speedup',variants={k:[{field:r[field] for field in ('pages','speedup','contracts','resources','median_ms')} for r in rs] for k,rs in results.items()}),indent=2)+'\n')
if __name__=='__main__':main()
